    /**
     * Tests getting all Wishlists.
     *
     * @return    Collection
     */
    public List<Wishlist> testGetAll() throws Throwable {
    LOGGER.info( "WishlistTest:testGetAll() - Retrieving Collection of Wishlists:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Wishlist : " );
    List<Wishlist> collection  = null;

    try {
        // call the static get method on the WishlistService
        collection = service.getAllWishlist();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Wishlist currEntity  = null;
            Iterator<Wishlist> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getWishlistId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

